import Link from "next/link";
import type { OrderStatus, Prisma } from "@prisma/client";
import { Download } from "lucide-react";
import { db } from "@/lib/db";
import { formatINR } from "@/lib/money";
import { cn, formatDate } from "@/lib/utils";
import { PageHeader, Table, td } from "@/components/admin/ui";
import { OrderStatusBadge, ORDER_STATUSES, statusLabel } from "@/components/OrderStatus";
import { PaymentBadge } from "@/components/PaymentBadge";

const METHODS = ["upi", "card", "netbanking", "wallet", "emi", "cardless_emi", "paylater"];

export default async function AdminOrders({ searchParams }: PageProps<"/admin/orders">) {
  const sp = await searchParams;
  const status = typeof sp.status === "string" && (ORDER_STATUSES as readonly string[]).includes(sp.status) ? (sp.status as OrderStatus) : undefined;
  const method = typeof sp.method === "string" && METHODS.includes(sp.method) ? sp.method : undefined;
  const q = typeof sp.q === "string" ? sp.q.trim() : "";

  const where: Prisma.OrderWhereInput = {
    ...(status ? { status } : { status: { not: "PENDING_PAYMENT" } }),
    ...(method ? { paymentMethod: method } : {}),
    ...(q ? { OR: [{ orderNumber: { contains: q, mode: "insensitive" } }, { email: { contains: q, mode: "insensitive" } }, { phone: { contains: q } }] } : {}),
  };
  const [orders, counts] = await Promise.all([
    db.order.findMany({ where, orderBy: { createdAt: "desc" }, take: 200, include: { _count: { select: { items: true } } } }),
    db.order.groupBy({ by: ["status"], _count: true }),
  ]);
  const count = (s: string) => counts.find((c) => c.status === s)?._count ?? 0;
  const qs = new URLSearchParams(Object.entries({ status, method, q }).filter(([, v]) => v) as [string, string][]).toString();

  return (
    <>
      <PageHeader title="Orders" description="Paid and fulfilled orders. Abandoned payment attempts are under “Pending payment”." actions={<a href={`/api/admin/export?type=orders&${qs}`} className="btn-outline"><Download className="h-4 w-4" /> Export CSV</a>} />
      <div className="no-scrollbar mb-4 flex gap-1 overflow-x-auto text-sm">
        <Link href="/admin/orders" className={cn("whitespace-nowrap rounded-full px-3 py-1.5", !status ? "bg-ink text-white" : "bg-white")}>All</Link>
        {ORDER_STATUSES.map((s) => (
          <Link key={s} href={`/admin/orders?status=${s}`} className={cn("whitespace-nowrap rounded-full px-3 py-1.5", status === s ? "bg-ink text-white" : "bg-white")}>
            {statusLabel(s)} <span className="opacity-60">{count(s)}</span>
          </Link>
        ))}
      </div>
      <form className="mb-4 flex flex-wrap gap-2">
        {status && <input type="hidden" name="status" value={status} />}
        <input name="q" defaultValue={q} placeholder="Order #, email or phone" className="input max-w-xs" />
        <select name="method" defaultValue={method ?? ""} className="input w-auto">
          <option value="">Any payment method</option>
          {METHODS.map((m) => <option key={m} value={m}>{m.replace("_", " ")}</option>)}
        </select>
        <button className="btn-dark">Search</button>
      </form>
      <div className="rounded-lg border border-line bg-white">
        <Table head={["Order", "Date", "Customer", "Items", "Total", "Payment", "Status"]}>
          {orders.map((o) => {
            const a = o.shippingAddress as Record<string, string>;
            return (
              <tr key={o.id}>
                <td className={td}><Link href={`/admin/orders/${o.id}`} className="font-semibold hover:text-maroon">#{o.orderNumber}</Link></td>
                <td className={cn(td, "whitespace-nowrap text-muted")}>{formatDate(o.createdAt, true)}</td>
                <td className={td}>{a.name}<span className="block text-xs text-muted">{a.city} · {o.phone}</span></td>
                <td className={cn(td, "tabular-nums")}>{o._count.items}</td>
                <td className={cn(td, "font-medium tabular-nums")}>{formatINR(o.total)}</td>
                <td className={cn(td, "text-xs")}><PaymentBadge method={o.paymentMethod} details={o.paymentDetails as Record<string, string | number | null> | null} /></td>
                <td className={td}><OrderStatusBadge status={o.status} /></td>
              </tr>
            );
          })}
        </Table>
        {!orders.length && <p className="p-8 text-center text-sm text-muted">No orders found.</p>}
      </div>
    </>
  );
}
